            Q("gnn_msg_q1", "choice", "GNN", "一层 GNN 更新节点靠？", ["聚合邻居信息", "只看自己", "随机初始化", "全局池化"], 0, 120, "邻居特征聚合后变换，得到新表示。", ["聚合邻居", "答案就出来了。"]),
            Q("gnn_msg_q2", "fill", "图神经网络/消息传递", "图含节点0,1,2，边 0–1、1–2，节点特征 h=[1,2,3]。一次消息传递（无自环、sum 聚合邻居特征）后，三节点新特征之和是？", null, "8", 140, "各节点只加邻居：2,1+3,2 → 2,4,2，和是8，自环没开别乱加自己。", ["节点0 邻居只有1，新值=h₁=2。", "节点1 邻居是0和2，新值=1+3=4；节点2 邻居是1，新值=2。", "三节点新特征 [2,4,2] 之和=8。", "答案就出来了。"], "hard"),
            Q("gnn_msg_q3", "choice", "图神经网络", "图神经网络消息传递(message passing)的核心步骤是？", ["仅用自身特征更新", "先聚合邻居消息再更新自身", "直接删除边", "只做全局池化"], 1, 110, "消息传递先收邻居信再更新自己。", ["每一层先把邻居特征做消息变换。", "再聚合(求和/均值/最大值)并更新节点表示。", "答案就出来了。"]),
            Q("gnn_msg_q4", "choice", "图神经网络", "节点 v 的三个邻居特征为 [1,2,3]，采用均值聚合(mean aggregation)，聚合结果为？", ["6", "2", "3", "1.5"], 1, 140, "均值聚合就是把邻居加起来除以个数，2。", ["均值聚合 = 邻居特征之和 / 邻居数。", "(1+2+3)/3 = 6/3 = 2。", "答案就出来了。"], "hard")
