            Q("graph_cent_q1", "choice", "图论", "度中心性衡量？", ["连接数多少", "距离远近", "聚类", "权重和"], 0, 120, "度就是连了几条边，越多越中心。", ["连接数", "答案就出来了。"]),
            Q("graph_cent_q2", "fill", "图论/中心性", "4节点图，边：A–B, B–C, B–D, C–D。问节点 B 的介数中心性（经过B的最短路径条数）是多少？", null, "2", 150, "B只在A–C和A–D最短路中间，C–D走直连不劳B，计2。", ["节点对共 C(4,2)=6 对，看哪些最短路径必经 B。", "A–C 唯一最短路 A–B–C、A–D 唯一最短路 A–B–D，都经过 B（计2）。", "C–D 有直连边不需绕 B；其余对不含 B，故介数为 2。", "答案就出来了。"], "hard"),
            Q("graph_cent_q3", "choice", "图算法", "度中心性(degree centrality)衡量的是？", ["节点的邻居数量", "节点的颜色", "边的权重", "图的面积"], 0, 100, "度中心性数数你跟几个邻居勾肩搭背。", ["度中心性定义为节点度数(相邻边数)。", "即与该节点直接相连的邻居个数。", "答案就出来了。"]),
            Q("graph_cent_q4", "choice", "图算法", "5 个节点组成的星型图中，中心节点与另外 4 个都相连。其归一化度中心性(除以 n−1)为？", ["1", "0.25", "4", "0.5"], 0, 130, "星图中心连 4 个，归一化除以 4 得满分 1。", ["中心节点度数 = 4（连其余 4 个）。", "归一化 = 4/(5−1) = 1。", "答案就出来了。"], "hard")
